import{z as B,x as d,o as e,c as n,q as t,j as r,D as a,d as i,s,S as A}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"KVM 与 QEMU","description":"","frontmatter":{"title":"KVM 与 QEMU","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-kvm-qemu.md","filePath":"cs/virt-kvm-qemu.md","lastUpdated":1791063341000}'),l={name:"cs/virt-kvm-qemu.md"};function M(m,E,p,U,c,v){const o=d("Mermaid");return e(),n("div",null,[E[2]||(E[2]=t('<h1 id="kvm-与-qemu" tabindex="-1">KVM 与 QEMU <a class="header-anchor" href="#kvm-与-qemu" aria-label="Permalink to &quot;KVM 与 QEMU&quot;">​</a></h1><div class="epigraph"><p>KVM 管住陷入、内存与寄存器状态；QEMU 管设备与生命周期。这条内核与用户态的接缝不是分工史，而是一道可以挪动的成本线：每挪一次，都在回答「哪些退出值得付一次用户态往返」。</p><footer>—— 据 Linux KVM API 文档与 QEMU 设计文档整理</footer></div><p><a href="/cs/virt-hypervisor-types">上一课</a>把虚拟化钉成陷入机制的谱系，并说明 KVM 选择了「复用宿主内核、只补陷入」的路线。本课拆这条路线的内部：KVM 与 QEMU 的边界怎么划、划在哪里，以及为什么这道接缝持续在被挪。主干课<a href="/cs/kvm-qemu">KVM 与 QEMU 分工</a>给过 ioctl 的轮廓；本课深钻控制平面的形状与数据平面的迁移。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从系统调用面看，KVM 是一个字符设备：<code>ioctl(/dev/kvm)</code> 先建 VM（返回一个 vm fd），在 vm fd 上设内存槽、建 vCPU（每个 vCPU 又是一个 fd），之后每个 vCPU 线程循环调用 <code>KVM_RUN</code>，进非根模式跑客户代码。退出的处置分两层：MMU 缺页、多数寄存器类退出由 KVM 在内核内闭环处理，vCPU 不离开内核；设备 I/O、停止指令、用户关心的配置变更才返回 QEMU 用户态。缺口是：<strong>两层怎么分、为什么这么分</strong>。分错的方向有两个——把设备模拟全塞进内核，内核膨胀成第二个 QEMU；把陷入处理全放用户态，每次敏感指令都付一次用户态往返。</p>',5)),(e(),r(A,null,{default:a(()=>[s(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22%E6%89%93%E5%BC%80%20%2Fdev%2Fkvm%22%5D%20--%3E%20IO1%5B%22ioctl%20%E5%BB%BA%20VM%2C%20%E5%BE%97%20vm%20fd%22%5D%0A%20%20IO1%20--%3E%20IO2%5B%22%E8%AE%BE%E5%86%85%E5%AD%98%E6%A7%BD%3A%20%E5%AE%A2%E7%89%A9%E7%90%86%E5%8C%BA%E9%97%B4%E6%98%A0%E5%B0%84%E5%AE%BF%E4%B8%BB%20mmap%22%5D%0A%20%20IO2%20--%3E%20IO3%5B%22%E6%AF%8F%E4%B8%AA%20vCPU%20%E5%BB%BA%E4%B8%80%E4%B8%AA%20fd%22%5D%0A%20%20IO3%20--%3E%20LOOP%5B%22vCPU%20%E7%BA%BF%E7%A8%8B%E5%BE%AA%E7%8E%AF%20KVM_RUN%22%5D%0A%20%20LOOP%20--%3E%20EXITQ%7B%22%E9%80%80%E5%87%BA%E5%8E%9F%E5%9B%A0%E6%98%AF%E4%BB%80%E4%B9%88%22%7D%0A%20%20EXITQ%20--%3E%7C%22%E5%86%85%E6%A0%B8%E5%8F%AF%E9%97%AD%E7%8E%AF%22%7C%20LOOP%0A%20%20EXITQ%20--%3E%7C%22%E8%AE%BE%E5%A4%87%E6%88%96%E9%85%8D%E7%BD%AE%E7%B1%BB%22%7C%20USER%5B%22%E8%BF%94%E5%9B%9E%20QEMU%20%E5%A4%84%E7%BD%AE%E5%90%8E%E9%87%8D%E5%85%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把接缝当成设计对象：先看清数据平面在接缝的哪一侧，再看把它挪过接缝要付什么。</p><h3 id="接缝怎么挪" tabindex="-1">接缝怎么挪 <a class="header-anchor" href="#接缝怎么挪" aria-label="Permalink to &quot;接缝怎么挪&quot;">​</a></h3><p>数据平面的大头是 virtio 后端。最早的形状是「客机踢环，QEMU 用户线程收请求，再替它调宿主系统调用」：每笔 I/O 两次上下文切换加一次内核路径。vhost 把后端挪进内核专一线程，数据路径不再进 QEMU；vhost-user 再挪一步，后端可以是任意进程，与 QEMU 共享客户内存、用 Unix 套接字协商——这正是 <a href="/cs/virtio">virtio</a> 环契约的兑现：接口固定后，谁在另一端实现它都可以。ioeventfd 与 irqfd 是接缝上的两个孔：客机写门铃和宿主回中断都被翻译成事件fd，绕过 <code>KVM_RUN</code> 返回，vCPU 不必被叫醒。</p><p><span class="marginnote">数字实例：一次「返回 QEMU」的往返按微秒量级计，ioeventfd 让门铃写直达内核后端后，每笔 I/O 省下的就是这一两个微秒；万兆网卡十万包每秒的负载上，这笔固定开销乘出来是按 CPU 核数算的账。</span></p>',5)),(e(),r(A,null,{default:a(()=>[s(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20VT%5B%22vCPU%20%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%7C%22KVM_RUN%22%7C%20KVM%5B%22KVM%20%E5%86%85%E6%A0%B8%22%5D%0A%20%20KVM%20--%3E%7C%22%E5%86%85%E6%A0%B8%E5%86%85%E9%97%AD%E7%8E%AF%3A%20EPT%20%E7%BC%BA%E9%A1%B5%E7%AD%89%22%7C%20KVM%0A%20%20KVM%20--%3E%7C%22%E8%AE%BE%E5%A4%87%E7%B1%BB%E9%80%80%E5%87%BA%22%7C%20QEMU%5B%22QEMU%20%E7%94%A8%E6%88%B7%E6%80%81%E8%AE%BE%E5%A4%87%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20QEMU%20--%3E%7C%22ioeventfd%20%E7%BB%95%E8%A1%8C%22%7C%20BACK%5B%22vhost%20%E5%86%85%E6%A0%B8%E5%90%8E%E7%AB%AF%22%5D%0A%20%20BACK%20--%3E%20NET1%5B%22%E5%AE%BF%E4%B8%BB%E5%9D%97%E5%B1%82%E6%88%96%E7%BD%91%E5%8D%A1%22%5D%0A%20%20QEMU%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%3A%20%E8%BF%81%E7%A7%BB%2C%20%E5%BF%AB%E7%85%A7%2C%20%E7%83%AD%E6%8F%92%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么值得这么折腾？把退出按频次分类就清楚了。低频退出（配置、迁移、热插）付用户态往返无所谓，换来的是设备模型活在可崩溃、可升级、可复用的进程里——QEMU 数十年积累的设备动物园不必进内核；高频路径（每包、每块）哪怕几百纳秒的固定开销也会乘上吞吐。所以演进方向一致：<strong>高频路径内移或旁路，低频路径留在用户态</strong>。内存槽是另一半契约：QEMU 把客户 RAM 保留为进程里的一段 mmap，用 <code>KVM_SET_USER_MEMORY_REGION</code> 把客户物理地址区间映射到宿主虚拟地址；EPT 负责客户物理到宿主物理的翻译（详见<a href="/cs/shadow-page-table">影子页表</a>），QEMU 仍然只看见自己的用户页——内存的所有权没有挪，挪的只是热路径。</p><p><span class="marginnote">内存槽可以翻译成「客机地址的翻译合同」：QEMU 把一段自己 mmap 出来的用户内存报给 KVM，说「客物理地址 0 到 2GB 落在这里」；之后客机每访问一个地址，EPT 按这份合同直接翻成宿主物理地址，QEMU 从头到尾只看见普通用户页。</span></p><p><span class="marginnote">vhost-net 的内核后端线程直接对接 tap 设备，数据包不再穿过 QEMU 进程；代价是后端逻辑进了内核、错误以内核为边界。vhost-user（如 OVS、SPDK 场景）把后端放回独立进程，共享内存换回隔离，套接字承担控制协商——同一条 seam 的两个方向。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 VMX 字段与退出原因码的清单，那是 <a href="/cs/vmx-vmexit">VMX 与 VM exit</a> 的对象；vDPA、virtio 数据面标准化进程也只承认存在。接缝的位置随版本移动，本课钉的是<strong>判据</strong>（退出频次 × 往返成本），不是某一版 QEMU 的模块图。另一个边界：KVM/QEMU 的分工是同一台宿主内的事，跨宿主的一致性与迁移归<a href="/cs/live-migration">热迁移</a>。</p><p>把 QEMU 当「纯粹的模拟器」是反向误读：没有 KVM 时 QEMU 才做整台机器的指令翻译；有 KVM 时它几乎是纯设备模型加控制面。同一段代码两种角色，读性能报告前先确认跑了哪种模式。</p><p><span class="marginnote">常见误区：把 QEMU 一律当「逐条翻译指令的模拟器」来看性能报告。有 KVM 时指令全是 CPU 原生跑的，它几乎只做设备模型加控制面；只有无 KVM 的旧模式下才整台机器翻译——报告数字差一个量级，先查模式再下结论。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制面是一条 ioctl 链：建 VM、设内存槽、建 vCPU、循环 <code>KVM_RUN</code>。</li><li>退出分两层：内核内闭环处理高频 MMU 类，设备类才进 QEMU 用户态。</li><li>vhost 与 vhost-user 把 virtio 后端挪出 QEMU；ioeventfd/irqfd 让门铃与中断绕开 <code>KVM_RUN</code> 往返。</li><li>接缝挪动的判据是退出频次乘往返成本；低频路径留在用户态换设备生态。</li><li>出处：据 Linux KVM API 文档、QEMU 与 vhost 设计文档整理。</li></ul>',10))])}const V=B(l,[["render",M]]);export{_ as __pageData,V as default};
